#pragma oncenamespace n_RSUs{  template<class tIterable>  class base_iterator  {  public:    typedef tIterable                       type_value;  private:    typedef typename tIterable::iterator    type_iterator;    typedef typename tIterable::value_type  type_reference;    type_iterator m_it, m_end;  public:    base_iterator( tIterable &cont )    {      m_it = cont.begin();      m_end = cont.end();    }    base_iterator operator++()    {      ++m_it;      return ( *this );    }    base_iterator operator--()    {      --m_it;      return ( *this );    }    operator bool() const    {      return ( m_it != m_end );    }    type_value *operator->()    {      return &( *m_it );    }    type_reference &operator *()    {      return *m_it;    }    type_iterator GetPosition()    {      return m_it;    }  };};